import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}       # id -> [side, price, qty_remaining, active]
    seq_counter = [0]

    def add_order(oid, side, price, qty):
        book[oid] = [side, price, qty, True]
        seq = seq_counter[0]
        seq_counter[0] += 1
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def peek_best_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info[3] or info[2] <= 0:
                heapq.heappop(buy_heap)
                continue
            return buy_heap[0]
        return None

    def peek_best_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info[3] or info[2] <= 0:
                heapq.heappop(sell_heap)
                continue
            return sell_heap[0]
        return None

    def match_incoming(incoming_id, side, qty, price_limit):
        remaining = qty
        if side == 'buy':
            while remaining > 0:
                top = peek_best_sell()
                if top is None:
                    break
                sell_price, seq, sell_id = top
                if price_limit is not None and sell_price > price_limit:
                    break
                resting = book[sell_id]
                trade_qty = min(remaining, resting[2])
                trades.append([incoming_id, sell_id, sell_price, trade_qty])
                resting[2] -= trade_qty
                remaining -= trade_qty
        else:
            while remaining > 0:
                top = peek_best_buy()
                if top is None:
                    break
                negprice, seq, buy_id = top
                buy_price = -negprice
                if price_limit is not None and buy_price < price_limit:
                    break
                resting = book[buy_id]
                trade_qty = min(remaining, resting[2])
                trades.append([buy_id, incoming_id, buy_price, trade_qty])
                resting[2] -= trade_qty
                remaining -= trade_qty
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid][3]:
                book[oid][3] = False
        elif typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(oid, side, qty, price)
            if remaining > 0:
                add_order(oid, side, price, remaining)
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            match_incoming(oid, side, qty, price)
            # remainder discarded, not added to book
        elif typ == 'market':
            _, oid, side, qty = order
            match_incoming(oid, side, qty, None)
            # remainder discarded, not added to book

    return trades

